$targets = @(
  (Join-Path $env:TEMP 'nginxui-db-read.mjs'),
  (Join-Path $env:TEMP 'nginxui-db-del.mjs'),
  (Join-Path $env:TEMP 'captcha-zoom.png'),
  (Join-Path $env:TEMP 'rescue-hop5-detail.png')
)
foreach ($dir in @('C:\Users\Public', $env:TEMP)) {
  if (-not $dir) { continue }
  Get-ChildItem -LiteralPath $dir -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -like 'rescue-*.png' -or $_.Name -eq 'captcha-zoom.png' -or $_.Name -like 'nginxui-db-*.mjs' } | ForEach-Object { $targets += $_.FullName }
}
$roots = @($env:TEMP, 'C:\Users\Public') | Where-Object { $_ } | ForEach-Object { [System.IO.Path]::GetFullPath($_) }
$targets | Select-Object -Unique | ForEach-Object {
  if (-not $_) { return }
  $full = [System.IO.Path]::GetFullPath([string]$_)
  $ok = $false
  foreach ($r in $roots) { if ($full.StartsWith($r, [StringComparison]::OrdinalIgnoreCase)) { $ok = $true } }
  if (-not $ok) { Write-Output "SKIP $full"; return }
  if (Test-Path -LiteralPath $full) {
    Remove-Item -LiteralPath $full -Force
    Write-Output ("DELETED $full exists=" + (Test-Path -LiteralPath $full))
  } else { Write-Output "ABSENT $full" }
}
$state = 'D:\repository\苏住房防汛C端\.task-state'
Write-Output '---TASKSTATE-BEFORE---'
if (Test-Path -LiteralPath $state) { Get-ChildItem -LiteralPath $state -Force | ForEach-Object { $_.Name } } else { Write-Output 'NO_DIR' }
foreach ($n in @('build-h5-hop5.log','build-h5-hop5.state.json')) {
  $p = Join-Path $state $n
  if (Test-Path -LiteralPath $p) { Remove-Item -LiteralPath $p -Force; Write-Output "DELETED $p" }
}
$left = @()
if (Test-Path -LiteralPath $state) { $left = @(Get-ChildItem -LiteralPath $state -Force -ErrorAction SilentlyContinue) }
Write-Output ("LEFT=" + $left.Count)
if ((Test-Path -LiteralPath $state) -and $left.Count -eq 0) { Remove-Item -LiteralPath $state -Force; Write-Output 'REMOVED_DIR' }
Write-Output '---TASKSTATE-AFTER---'
Write-Output ("DIR_EXISTS=" + (Test-Path -LiteralPath $state))

